BEGIN;
-- PT104-S4-Q10
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch01$PT104-S4-Q10$batch01$ AND q.stimulus=$batch01$Unplugging a peripheral component such as a “mouse” from a personal computer renders all of the software programs that require that component unusable on that computer. On Fred’s personal computer, a software program that requires a mouse has become unusable. So it must be that the mouse for Fred’s computer became unplugged.$batch01$ AND q.prompt=$batch01$The argument is most vulnerable to which one of the following criticisms?$batch01$ AND q.correct_choice=$batch01$B$batch01$) THEN RAISE EXCEPTION 'Question changed: PT104-S4-Q10'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT104-S4-Q10$batch01$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT104-S4-Q10'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT104-S4-Q10$batch01$ AND c.letter=$batch01$A$batch01$ AND c.choice_text=$batch01$It contains a shift in the meaning of “unusable” from “permanently unusable” to “temporarily unusable.”$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT104-S4-Q10 A'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT104-S4-Q10$batch01$ AND c.letter=$batch01$B$batch01$ AND c.choice_text=$batch01$It treats an event that can cause a certain result as though that event is necessary to bring about that result.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT104-S4-Q10 B'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT104-S4-Q10$batch01$ AND c.letter=$batch01$C$batch01$ AND c.choice_text=$batch01$It introduces information unrelated to its conclusion as evidence in support of that conclusion.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT104-S4-Q10 C'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT104-S4-Q10$batch01$ AND c.letter=$batch01$D$batch01$ AND c.choice_text=$batch01$It attempts to support its conclusion by citing a generalization that is too broad.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT104-S4-Q10 D'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT104-S4-Q10$batch01$ AND c.letter=$batch01$E$batch01$ AND c.choice_text=$batch01$It overlooks the possibility that some programs do not require a peripheral component such as a mouse.$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT104-S4-Q10 E'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanation_steps s JOIN lr_explanations e ON e.id=s.explanation_id JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT104-S4-Q10$batch01$ AND e.style IN ('single','standard')) <> 0 OR (SELECT COUNT(*) FROM lr_explanation_choice_notes n JOIN lr_explanations e ON e.id=n.explanation_id JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT104-S4-Q10$batch01$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation changed: PT104-S4-Q10'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch01$PT104-S4-Q10$batch01$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch01$Conclusion$batch01$, $batch01$Fred's mouse became unplugged.$batch01$), (1, $batch01$Evidence$batch01$, $batch01$Unplugging a required component makes a program unusable; Fred's mouse-requiring program is unusable.$batch01$), (2, $batch01$Evaluate$batch01$, $batch01$The rule says *mouse unplugged → program unusable*. Fred has the result, so the argument runs backward to the cause. But a broken mouse, corrupted software, or another failure might also make the program unusable. We need no proof that one of those happened. Their possibility shows that unusability does not establish disconnection.$batch01$), (3, $batch01$Goal$batch01$, $batch01$Find the confusion of a sufficient cause with a necessary cause of the result.$batch01$)) v(position,label,body) WHERE q.qid=$batch01$PT104-S4-Q10$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch01$A$batch01$, $batch01$“Unusable” need not shift between permanent and temporary meanings. A program can be unusable for several reasons under the same ordinary meaning.$batch01$), ($batch01$B$batch01$, $batch01$An unplugged mouse *can* cause unusability. The argument treats unplugging as though it *must* be the cause whenever such a program is unusable. This is the illegal reversal of the conditional.$batch01$), ($batch01$C$batch01$, $batch01$The general fact about required peripherals is related to the conclusion. It just does not establish that this specific peripheral was unplugged.$batch01$), ($batch01$D$batch01$, $batch01$The generalization may be perfectly true. The flaw is applying it backward, not making it too broad.$batch01$), ($batch01$E$batch01$, $batch01$Fred's program explicitly requires a mouse. Whether other programs need no peripherals has no bearing on why this one became unusable.$batch01$)) v(letter,body) WHERE q.qid=$batch01$PT104-S4-Q10$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id) ON CONFLICT DO NOTHING;
COMMIT;
